import React, { useMemo, useRef, useState } from "react";
import VideoEditorPlayer from "./VideoEditorPlayer";
import { formatTime } from "./TimelineBar";

export default function Results({ result, videoUrl, backendBase }) {
  const [videoDuration, setVideoDuration] = useState(0);
  const ranges = result?.tampered_time_ranges || [];
  const duration = result?.duration || videoDuration || 0;

  const downloadUrl = backendBase + (result?.artifacts?.download_url || "");
  const annotatedVideoUrl = backendBase + (result?.artifacts?.annotated_video_url || "");
  const previewVideoUrl = result?.artifacts?.preview_video_url
    ? backendBase + result.artifacts.preview_video_url
    : "";

  const prettyRanges = useMemo(() => {
    if (!ranges?.length) return [];
    return ranges.map((r, i) => ({
      key: i,
      start_s: Number(r.start_s || 0),
      end_s: Number(r.end_s || 0),
    }));
  }, [ranges]);

  return (
    <div>
      <div style={styles.grid}>
        <div style={styles.panel}>
          <h3 style={styles.h3}>Video</h3>
          {videoUrl ? (
            <VideoEditorPlayer
              src={previewVideoUrl || videoUrl}
              tamperRanges={prettyRanges}
              onDuration={setVideoDuration}
            />
          ) : (
            <div style={styles.muted}>No video</div>
          )}
        </div>

        <div style={styles.panel}>
          <h3 style={styles.h3}>Result</h3>
          <div style={styles.badge(result.is_tampered)}>
            {result.is_tampered ? "Tampered Video Detected" : "No Tampering Detected"}
          </div>
          <div style={{ marginTop: 10, color: "#444" }}>
            <div style={{ color: "#6b7280" }}>{result.label || ""}</div>
            <div style={{ marginTop: 6, color: "#6b7280" }}>Duration: {formatTime(duration)}</div>
          </div>
          <div style={{ marginTop: 12, display: "flex", gap: 10, flexWrap: "wrap" }}>
            <a href={downloadUrl} style={styles.linkButton} target="_blank" rel="noreferrer">
              Download artifacts (ZIP)
            </a>
            <a href={annotatedVideoUrl} style={styles.linkButtonAlt} target="_blank" rel="noreferrer">
              View annotated video
            </a>
          </div>
        </div>
      </div>

      <div style={styles.panel}>
        <h3 style={styles.h3}>Tampering Detected At</h3>
        {prettyRanges.length ? (
          <ul style={{ marginTop: 8 }}>
            {prettyRanges.map((r) => (
              <li key={r.key} style={{ marginBottom: 6 }}>
                <span style={{ fontWeight: 700, color: "#b91c1c" }}>⚠</span>{" "}
                <button
                  type="button"
                  style={styles.timePillBtn}
                  onClick={() => {
                    // The editor timeline itself is the primary navigation; keep list as info only.
                    // (We intentionally avoid wiring a ref through multiple layers.)
                    const el = document.querySelector("video");
                    if (el) el.currentTime = r.start_s;
                  }}
                  title="Jump to this time"
                >
                  {formatTime(r.start_s)} – {formatTime(r.end_s)}
                </button>
              </li>
            ))}
          </ul>
        ) : (
          <div style={styles.muted}>No tampering intervals found</div>
        )}
      </div>
    </div>
  );
}

const styles = {
  grid: {
    display: "grid",
    gridTemplateColumns: "1.2fr 0.8fr",
    gap: 12,
  },
  panel: {
    border: "1px solid rgba(255,255,255,0.08)",
    borderRadius: 12,
    padding: 12,
    background: "rgba(255,255,255,0.04)",
  },
  h3: { margin: "4px 0 10px 0" },
  muted: { color: "#9ca3af" },
  badge: (isBad) => ({
    display: "inline-block",
    padding: "6px 10px",
    borderRadius: 999,
    fontWeight: 700,
    color: isBad ? "#7f1d1d" : "#0f5132",
    background: isBad ? "#fee2e2" : "#d1fae5",
    border: `1px solid ${isBad ? "#fecaca" : "#a7f3d0"}`,
  }),
  linkButton: {
    display: "inline-block",
    padding: "10px 12px",
    borderRadius: 10,
    background: "#ef4444",
    color: "white",
    textDecoration: "none",
    fontWeight: 600,
  },
  linkButtonAlt: {
    display: "inline-block",
    padding: "10px 12px",
    borderRadius: 10,
    background: "#111827",
    color: "white",
    textDecoration: "none",
    fontWeight: 600,
    border: "1px solid rgba(255,255,255,0.08)",
  },
  timePill: {
    display: "inline-block",
    padding: "4px 10px",
    borderRadius: 999,
    background: "#fee2e2",
    border: "1px solid #fecaca",
    color: "#7f1d1d",
    fontWeight: 700,
  },
  timePillBtn: {
    display: "inline-block",
    padding: "6px 12px",
    borderRadius: 999,
    background: "#fee2e2",
    border: "1px solid #fecaca",
    color: "#7f1d1d",
    fontWeight: 800,
    cursor: "pointer",
  },
};
